// Sign Up Page (Frame2)
class Frame2 extends StatefulWidget {
  const Frame2({super.key});

  @override
  State<Frame2> createState() => _Frame2State();
}

class _Frame2State extends State<Frame2> {
  final TextEditingController _companyController = TextEditingController();
  final TextEditingController _fullNameController = TextEditingController();
  final TextEditingController _phoneController = TextEditingController();
  final TextEditingController _crController = TextEditingController();
  final TextEditingController _passwordController = TextEditingController();
  bool _obscurePassword = true;

  bool _loading = false;

  Future<void> _register() async {
    setState(() => _loading = true);
    try {
      await ApiService.register(
        companyName: _companyController.text.trim(),
        fullName: _fullNameController.text.trim(),
        mobile: _phoneController.text.trim(),
        commercialReg: _crController.text.trim(),
        password: _passwordController.text,
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم إنشاء الحساب بنجاح!')),
      );
      Navigator.of(context).pushReplacement(
        MaterialPageRoute(builder: (context) => const Iphone1617Pro1()),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString())));
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  void dispose() {
    _companyController.dispose();
    _fullNameController.dispose();
    _phoneController.dispose();
    _crController.dispose();
    _passwordController.dispose();
    super.dispose();
  }

  Widget _buildInputField({
    required String label,
    required String hint,
    required TextEditingController controller,
    bool isPassword = false,
    TextInputType keyboardType = TextInputType.text,
