// Home Page (Iphone1617Pro1)
const _arMonths = [
  'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
  'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
];

class BookingCard extends StatelessWidget {
  final Booking booking;
  final VoidCallback? onTap;
  const BookingCard({super.key, required this.booking, this.onTap});

  (String, Color) _statusInfo(String s) {
    switch (s) {
      case 'Confirmed':
        return ('تم التأكيد', const Color(0xFF124C8F));
      case 'Loading':
        return ('جاري التحميل', const Color(0xFF0B7856));
      case 'Completed':
        return ('مكتمل', const Color(0xFFB8B0AE));
      default:
        return ('بانتظار التاكيد', const Color(0xFFD08C0B));
    }
  }

  @override
  Widget build(BuildContext context) {
    final b = booking;
    final (label, color) = _statusInfo(b.status);
    return GestureDetector(
      onTap: onTap,
      child: Container(
        height: 106,
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
        decoration: ShapeDecoration(
          color: const Color(0xFF18212C),
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.end,
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Row(
              textDirection: TextDirection.rtl,
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text('#${b.code}',
                    style: const TextStyle(
                        color: Colors.white, fontSize: 24, fontFamily: 'Inter', fontWeight: FontWeight.w700)),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
                  decoration: BoxDecoration(color: color, borderRadius: BorderRadius.circular(20)),
                  child: Text(label,
                      style: const TextStyle(
                          color: Colors.white, fontSize: 13, fontFamily: 'Inter', fontWeight: FontWeight.w700)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text('${b.cementType} . ${b.quantityTon.toStringAsFixed(0)} طن',
                textDirection: TextDirection.rtl,
                style: const TextStyle(color: Colors.white, fontSize: 14, fontFamily: 'Inter')),
            const SizedBox(height: 4),
            Text('${b.date.day} ${_arMonths[b.date.month - 1]}',
                textDirection: TextDirection.rtl,
                style: const TextStyle(color: Colors.white, fontSize: 14, fontFamily: 'Inter')),
          ],
        ),
      ),
    );
  }
}

class Iphone1617Pro1 extends StatefulWidget {
  const Iphone1617Pro1({super.key});

  @override
  State<Iphone1617Pro1> createState() => _Iphone1617Pro1State();
}

class _Iphone1617Pro1State extends State<Iphone1617Pro1> {
  String _name = '';
  int _count = 0;
  List<Booking>? _active;
  String? _listError;

  @override
  void initState() {
    super.initState();
    _loadMe();
  }

  Future<void> _loadMe() async {
    try {
      final me = await ApiService.getMe();
      if (!mounted) return;
      setState(() {
        _name = me.fullName;
        _count = me.activeBookings;
      });
    } catch (_) {}
    try {
      final list = await ApiService.getBookings(filter: 'active');
      if (!mounted) return;
      setState(() => _active = list);
    } catch (e) {
      if (!mounted) return;
      setState(() => _listError = e.toString());
    }
  }

  Widget _buildActiveList() {
    if (_listError != null) {
      return Center(
        child: Text(_listError!, textAlign: TextAlign.center, style: const TextStyle(color: Colors.white)),
      );
    }
    if (_active == null) {
      return const Center(child: CircularProgressIndicator());
    }
    if (_active!.isEmpty) {
      return const Center(
        child: Text('لا توجد حجوزات نشطة', style: TextStyle(color: Color(0xFF837777), fontSize: 16, fontFamily: 'Inter')),
      );
    }
    return ListView.separated(
      padding: EdgeInsets.zero,
      itemCount: _active!.length,
      separatorBuilder: (_, __) => const SizedBox(height: 16),
      itemBuilder: (context, i) => BookingCard(
        booking: _active![i],
        onTap: () => Navigator.of(context)
            .push(MaterialPageRoute(
            builder: (context) => Iphone1617Pro3(bookingId: _active![i].id)))
            .then((_) {
          setState(() {
            _active = null;
            _listError = null;
          });
          _loadMe();
        }),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        child: SingleChildScrollView(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Container(
                width: 402,
                height: 874,
                clipBehavior: Clip.antiAlias,
                decoration: ShapeDecoration(
                  color: const Color(0xFF0E141B),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
                child: Stack(
                  children: [
                    const Positioned(
                      right: 10,
                      top: 38,
                      child: Text(
