// Booking Details Page (Iphone1617Pro3)
class Iphone1617Pro3 extends StatefulWidget {
  final int? bookingId; // لو null يعرض آخر حجز للعميل
  const Iphone1617Pro3({super.key, this.bookingId});

  @override
  State<Iphone1617Pro3> createState() => _Iphone1617Pro3State();
}

class _Iphone1617Pro3State extends State<Iphone1617Pro3> {
  BookingDetails? _b;
  String? _error;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      int? id = widget.bookingId;
      if (id == null) {
        final list = await ApiService.getBookings();
        if (list.isEmpty) throw ApiException('لا توجد حجوزات');
        id = list.first.id;
      }
      final b = await ApiService.getBooking(id);
      if (!mounted) return;
      setState(() => _b = b);
    } catch (e) {
      if (!mounted) return;
      setState(() => _error = e.toString());
    }
  }

  (String, Color) _statusInfo(String s) {
    switch (s) {
      case 'Confirmed':
        return ('تم التأكيد', const Color(0xFF124C8F));
      case 'Loading':
        return ('جاري التحميل', const Color(0xFF0B7856));
      case 'Completed':
        return ('مكتمل', const Color(0xFFB8B0AE));
      default:
        return ('بانتظار التاكيد', const Color(0xFFD08C0B));
    }
  }

  String _clock(DateTime d) {
    final h = d.hour % 12 == 0 ? 12 : d.hour % 12;
    final m = d.minute.toString().padLeft(2, '0');
    return '$h:$m${d.hour < 12 ? 'ص' : 'م'}';
  }

  Future<void> _cancel() async {
    setState(() => _busy = true);
    try {
      await ApiService.cancelBooking(_b!.id);
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم إلغاء الحجز بنجاح.')),
      );
      Navigator.of(context).pop(true);
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString())));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Widget _row(String label, String? value) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(
            (value == null || value.isEmpty) ? '-' : value,
            textDirection: TextDirection.rtl,
            style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.w700),
          ),
          Text(label,
              style: const TextStyle(color: Color(0xFF837777), fontSize: 16, fontWeight: FontWeight.w700)),
        ],
      ),
    );
  }

  List<Widget> _timeline(BookingDetails b) {
    final steps = <(String, bool)>[
      ('تم انشاء الحجز  (${_clock(b.createdAt)})', true),
      ('تم تاكيد الحجز', b.status != 'Pending'),
      ('جاري التحميل', b.status == 'Loading' || b.status == 'Completed'),
      ('مكتمل', b.status == 'Completed'),
    ];
    final widgets = <Widget>[];
    for (var i = 0; i < steps.length; i++) {
      final top = 310.0 + i * 60;
      final done = steps[i].$2;
      widgets.add(Positioned(
        left: 330,
        top: top,
        child: Container(
          width: 25,
          height: 25,
          decoration: ShapeDecoration(
            color: done ? const Color(0xFF0B7856) : const Color(0xFF263241),
            shape: const OvalBorder(),
          ),
        ),
      ));
      widgets.add(Positioned(
        left: 170,
        top: top,
        child: Text(
          steps[i].$1,
          style: TextStyle(
            color: done ? Colors.white : const Color(0xFF837777),
            fontSize: 16,
            fontFamily: 'Inter',
            fontWeight: FontWeight.w700,
          ),
        ),
      ));
    }
    return widgets;
  }

  Widget _content(BookingDetails b) {
    final (label, color) = _statusInfo(b.status);
