class Iphone1617Pro11 extends StatelessWidget {
  const Iphone1617Pro11({super.key});

  @override
  Widget build(BuildContext context) {
    return const Iphone1617Pro10(initialFilter: 1);
  }
}

class _Iphone1617Pro10State extends State<Iphone1617Pro10> {
  late int _selectedFilter; // 0: الكل, 1: نشطة, 2: مكتملة
  List<Booking>? _items;
  String? _error;
  bool _loadingList = true;

  static const _months = [
    'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
    'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
  ];

  @override
  void initState() {
    super.initState();
    _selectedFilter = widget.initialFilter;
    _load();
  }

  Future<void> _load() async {
    setState(() {
      _loadingList = true;
      _error = null;
    });
    try {
      final f = _selectedFilter == 1 ? 'active' : _selectedFilter == 2 ? 'completed' : 'all';
      final list = await ApiService.getBookings(filter: f);
      if (!mounted) return;
      setState(() {
        _items = list;
        _loadingList = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = e.toString();
        _loadingList = false;
      });
    }
  }

  (String, Color) _statusInfo(String s) {
    switch (s) {
      case 'Confirmed':
        return ('تم التأكيد', const Color(0xFF124C8F));
      case 'Loading':
        return ('جاري التحميل', const Color(0xFF0B7856));
      case 'Completed':
        return ('مكتمل', const Color(0xFFB8B0AE));
      default:
        return ('بانتظار التاكيد', const Color(0xFFD08C0B));
    }
  }

  Widget _buildBookingsList() {
    if (_loadingList) {
      return const Center(child: CircularProgressIndicator());
    }
    if (_error != null) {
      return Center(
        child: Text(_error!, textAlign: TextAlign.center, style: const TextStyle(color: Colors.white)),
      );
    }
    final items = _items ?? [];
    if (items.isEmpty) {
      return const Center(
        child: Text('لا توجد حجوزات', style: TextStyle(color: Colors.white, fontSize: 18, fontFamily: 'Inter')),
      );
    }
    return RefreshIndicator(
      onRefresh: _load,
      child: ListView.separated(
        padding: EdgeInsets.zero,
        itemCount: items.length,
        separatorBuilder: (_, __) => const SizedBox(height: 16),
