// Notifications Page (Iphone1617Pro5)
class Iphone1617Pro5 extends StatefulWidget {
  const Iphone1617Pro5({super.key});

  @override
  State<Iphone1617Pro5> createState() => _Iphone1617Pro5State();
}

class _Iphone1617Pro5State extends State<Iphone1617Pro5> {
  List<AppNotif>? _items;
  String? _error;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _load(markRead: true);
    // تحديث تلقائي كل 10 ثواني عشان تجي الإشعارات الجديدة
    _timer = Timer.periodic(const Duration(seconds: 10), (_) => _load());
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  Future<void> _load({bool markRead = false}) async {
    try {
      final list = await ApiService.getNotifications();
      if (!mounted) return;
      setState(() {
        _items = list;
        _error = null;
      });
      if (markRead) {
        ApiService.markNotificationsRead().catchError((_) {});
      }
    } catch (e) {
      if (!mounted) return;
      if (_items == null) setState(() => _error = e.toString());
    }
  }

  (String, Color, IconData) _info(String status) {
    switch (status) {
      case 'Confirmed':
        return ('تم تأكيد حجزك', const Color(0xFF124C8F), Icons.check_circle_outline);
      case 'Loading':
        return ('بدأ تحميل شاحنتك', const Color(0xFF0B7856), Icons.local_shipping_outlined);
      case 'Completed':
        return ('اكتمل تحميل الحجز', const Color(0xFFB7AEAE), Icons.done_all_outlined);
      default:
        return ('حجزك بانتظار التأكيد', const Color(0xFFC98A0B), Icons.hourglass_top_outlined);
    }
  }

  String _ago(DateTime t) {
    final d = DateTime.now().difference(t);
    if (d.inMinutes < 1) return 'الآن';
    if (d.inMinutes < 60) return 'قبل ${d.inMinutes} دقيقة';
    if (d.inHours < 24) return 'قبل ${d.inHours} ساعة';
    return 'قبل ${d.inDays} يوم';
  }

  Widget _buildList() {
    if (_error != null) {
      return Center(
        child: Text(_error!, textAlign: TextAlign.center, style: const TextStyle(color: Colors.white)),
      );
    }
    if (_items == null) return const Center(child: CircularProgressIndicator());
    if (_items!.isEmpty) {
      return const Center(
        child: Text('لا توجد إشعارات', style: TextStyle(color: Color(0xFF837777), fontSize: 18, fontFamily: 'Inter')),
      );
    }
    return RefreshIndicator(
      onRefresh: _load,
      child: ListView.separated(
        padding: EdgeInsets.zero,
        itemCount: _items!.length,
        separatorBuilder: (_, __) => const SizedBox(height: 15),
        itemBuilder: (context, i) {
          final n = _items![i];
          final (title, color, icon) = _info(n.status);
          return _buildNotificationItem(
            context: context,
            title: title,
            subtitle: '#${n.bookingCode} . ${_ago(n.createdAt)}',
            iconColor: color,
            iconData: icon,
            onTap: () => Navigator.of(context).push(
              MaterialPageRoute(builder: (context) => Iphone1617Pro3(bookingId: n.bookingId)),
            ),
          );
        },
      ),
    );
  }

  Widget _buildNotificationItem({
    required BuildContext context,
    required String title,
    required String subtitle,
    required Color iconColor,
    required IconData iconData,
    required VoidCallback onTap,
  }) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        width: 370,
        height: 106,
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
        decoration: ShapeDecoration(
          color: const Color(0xFF18212C),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
        ),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.end,
          children: [
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                mainAxisAlignment: MainAxisAlignment.center,
